----- || LOADING CHECK || -----

if getgenv().luna_xyz_loading then return warn("[luna.xyz] Loading stopped. (ERROR: Loading)"); end;
if getgenv().luna_xyz_loaded then return warn("[luna.xyz] Loading stopped. (ERROR: Already loaded)"); end;

getgenv().luna_xyz_loading = true;
if not game:IsLoaded() then game.Loaded:Wait(); end;

----- || ENV INIT || -----

getgenv().luna_xyz_env = { loaded_libs = {}; discord_id = "https://discord.gg/z5V9EAnhzj"; };
local luna_xyz_env = getgenv().luna_xyz_env;

luna_xyz_env.supported_games = {

	["the_rakoof"] = {
		["GameId"] = 15367709476; ["Status"] = "🟢";
	};

	["rake_remastered"] = {
		["GameId"] = 2413927524; ["Status"] = "🟢";
	};

	["project_lazarus"] = {
		["GameId"] = 443406476; ["Status"] = "🟢";
	};
	
	["violence_district"] = {
		["GameId"] = 6739698191; ["Status"] = "🟢";
	};
	
	["skibidi_game"] = {

		["GameId"] = 93531785397649; ["Status"] = "🟢";
		["Hidden"] = true;
	};
};

----- || FILESYSTEM + UTILS || -----

local hasFS, hasRead, hasDelete = (writefile and isfile and readfile), (isfile and readfile), (isfile and delfile);

function luna_xyz_env:LoadRemote(url, ...)
	
	local args = table.pack(...);
	
	local __s, __d = pcall(function()
		return loadstring(game:HttpGet(url))(table.unpack(args, 1, args.n));
	end);
	
	return __d;
end;

function luna_xyz_env:LoadLocalOrRemote(path, url, ...)

	if hasRead and isfile(path) then
		
		local args = table.pack(...);

		local __s, __d = pcall(function()
			return loadstring(readfile(path))(table.unpack(args, 1, args.n));
		end);

		if __s then return __d end;
	end;

	return luna_xyz_env:LoadRemote(url, ...);
end;

function luna_xyz_env:ShowErrorPage(ShowError, ErrorMessage)
	
	luna_xyz_env.LoadingUI:ShowErrorPage(ShowError);
	luna_xyz_env.LoadingUI:SetErrorMessage(ErrorMessage);

	luna_xyz_env.LoadingUI:SetErrorButtons({

		Retry = {

			Title = "Retry"; Variant = "Primary";

			Callback = function()

				luna_xyz_env.LoadingUI:Destroy();
				luna_xyz_env.Library:Unload();

				getgenv().luna_xyz_loading = false;
				getgenv().luna_xyz_loaded = false;

				luna_xyz_env:LoadRemote("https://api.jnkie.com/api/v1/luascripts/public/fac6b129defbda2cf7d7a4cfaf9a7ae28589934ccb46cb06858577fd2c34e64b/download");
			end;
		};

		Close = {

			Title = "Close"; Variant = "Destructive";

			Callback = function()

				luna_xyz_env.LoadingUI:Destroy();
				luna_xyz_env.Library:Unload();

				getgenv().luna_xyz_loading = false;
				getgenv().luna_xyz_loaded = false;
			end;
		};
	});
end;

function luna_xyz_env:KeyFail(KeyWindow, title, description)

	KeyWindow:AddDialog("DialogueIdx", {

		Title = title; Description = description;
		AutoDismiss = true; OutsideClickDismiss = true;

		FooterButtons = {

			Confirm = {

				Title = "OK"; Variant = "Primary",
				WaitTime = 1; Order = 1;
			};

			Close = {

				Title = "Retry"; Variant = "Destructive",
				WaitTime = 1; Order = 2;

				Callback = function()

					luna_xyz_env.LoadingUI:Destroy();
					luna_xyz_env.Library:Unload();

					luna_xyz_env:LoadRemote("https://api.jnkie.com/api/v1/luascripts/public/fac6b129defbda2cf7d7a4cfaf9a7ae28589934ccb46cb06858577fd2c34e64b/download");
				end;
			};
		};
	});
end;

function luna_xyz_env:SetProgress(desc, step, _delay)	
	luna_xyz_env.LoadingUI:SetDescription(desc); luna_xyz_env.LoadingUI:SetCurrentStep(step);
end;

function luna_xyz_env:ColorToRGB(color)
	return string.format("%d,%d,%d", math.floor(color.R * 255), math.floor(color.G * 255), math.floor(color.B * 255));
end;

----- || LIBRARIES || -----

local UILibrary = luna_xyz_env:LoadLocalOrRemote("luna_xyz/utils/ui/Library.lua", "https://raw.githubusercontent.com/deividcomsono/Obsidian/main/Library.lua");
luna_xyz_env.versions = luna_xyz_env:LoadLocalOrRemote("luna_xyz/utils/versions.lua","https://raw.githubusercontent.com/00lxh/luna_xyz/main/src/versions.lua");

----- ||LOADING UI || -----

luna_xyz_env.LoadingUI = UILibrary:CreateLoading({
	
	Title = ('luna.xyz - %s'):format(tostring(luna_xyz_env.versions["luna_xyz_loader"]));
	TotalSteps = 15; Icon = 5012126105; IconSize = UDim2.fromOffset(20, 20);
});

luna_xyz_env.LoadingUI:SetMessage("Initializing luna.xyz");
luna_xyz_env:SetProgress("Checking Executor..", 1);

if table.find({ "xeno", "solara" }, tostring(identifyexecutor()):lower()) then
	return luna_xyz_env:ShowErrorPage(true, 'luna.xyz was unable to load (<b>ERROR: Executor not supported.</b>)\n\nIf the error persists, try using a different executor with high sUNC.');
end;

----- || LOGGING INIT || -----

task.wait(.3);
luna_xyz_env:SetProgress("Initializing luna.xyz env..", 2);

local date = os.date("*t");

local current_date = string.format("%02d-%02d-%04d", date.month, date.day, date.year);
local savePath = "luna_xyz/saves/save_logs.txt";

if hasFS then
	
	local content = isfile(savePath) and readfile(savePath) or "true";
	writefile(savePath, content);
end;

if hasDelete and isfile(('luna_xyz/logs/%s.log'):format(current_date)) then delfile(('luna_xyz/logs/%s.log'):format(current_date)); end;
local Logger = luna_xyz_env:LoadRemote("https://raw.githubusercontent.com/00lxh/roblox-logger/refs/heads/main/logger.lua");

Logger:SetSaveLocation("luna_xyz/logs/"); Logger:ToggleLogs(hasRead and isfile(savePath) and readfile(savePath) == "true");
Logger:ToggleConsoleLogs(hasRead and isfile(savePath) and readfile(savePath) == "true");

Logger.event(('Log created on date %s on version and executor %s - %s.'):format(current_date, tostring(luna_xyz_env.versions["luna_xyz_loader"]), identifyexecutor(), select(2, identifyexecutor())));
Logger.event(('Initializing luna.xyz - %s..'):format(tostring(luna_xyz_env.versions["luna_xyz_loader"])));

----- || FILE MANAGER || -----

task.wait(.3);
luna_xyz_env:SetProgress("Checking files integrity..", 3);

local FileManager = luna_xyz_env:LoadRemote("https://raw.githubusercontent.com/00lxh/luna_xyz/main/src/utils/system/FileManager.lua");
repeat task.wait() until FileManager and FileManager.FilesLoaded;

----- || GAME DETECTION || -----

task.wait(.3);
luna_xyz_env:SetProgress("Fetching game data..", 4);

for name, info in pairs(luna_xyz_env.supported_games) do

	if not (game.PlaceId == info.GameId or game.GameId == info.GameId) then continue; end;
	luna_xyz_env.ScriptLoader = name;

	luna_xyz_env.ScriptName = name:gsub("_", " "):gsub("(%a)(%w*)", function(a, b)
		return a:upper() .. b:lower();
	end);

	break;
end;

if not luna_xyz_env.ScriptLoader then
	Logger.error('Failed to load luna.xyz script'); Logger.error('    RUNTIME ERROR: Game not supported');
end;

luna_xyz_env:ShowErrorPage(not luna_xyz_env.ScriptLoader, 'luna.xyz was unable to load (<b>ERROR: Game not supported.</b>)\n\nIf the error persists, please contact the development team.');
if not luna_xyz_env.ScriptLoader then return; end;

luna_xyz_env.Maid = luna_xyz_env:GetService("Maid").new();
luna_xyz_env.HookService = luna_xyz_env:GetService("HookService");

task.wait(.3);
luna_xyz_env:SetProgress(('%s data loaded.'):format(luna_xyz_env.ScriptName), 5);

----- || USER AUTH || -----

local UIManager = luna_xyz_env:GetService("UIManager");
local attempts, maxAttempts, user_authenticated = 0, 5 , false;

task.wait(.3);

luna_xyz_env:SetProgress("Authenticating user..", 6);
Logger.debug('Authenticating user..');

local Junkie = loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))();
Junkie.service = "luna.xyz"; Junkie.provider = "luna_key_system"; Junkie.identifier = "1008004";

local current_key = (hasRead and isfile("luna_xyz/core/luna_key.txt") and readfile("luna_xyz/core/luna_key.txt")) or "";

local KeyWindow; pcall(function()
	
	local validation = Junkie.check_key(current_key);
	if validation.valid then user_authenticated = true; getgenv().SCRIPT_KEY = current_key; return; end;
	
	KeyWindow = UIManager:CreateKeyWindow(function(receivedKey)

		if attempts >= maxAttempts then
			return luna_xyz_env:KeyFail(KeyWindow, "RATE_LIMITED", "Too much failed attempts, Please restart luna.xyz.");
		end;

		if not luna_xyz_env:IsString(receivedKey) then
			return luna_xyz_env:KeyFail(KeyWindow, "INVALID_STRING", "Please provide a valid string.");
		end;

		attempts += 1; getgenv().SCRIPT_KEY = receivedKey;
		validation = Junkie.check_key(receivedKey);

		if validation.valid then

			user_authenticated = true;
			return (hasFS and writefile("luna_xyz/core/luna_key.txt", receivedKey));
		end;

		local errorMsg = validation.error or "Unknown error";

		if errorMsg == "KEY_INVALID" or errorMsg == "KEY_EXPIRED" or errorMsg == "ALREADY_USED" or errorMsg == "SERVICE_MISMATCH" then
			return luna_xyz_env:KeyFail(KeyWindow, errorMsg, "The provided key is invalid or expired.");
		end;

		if errorMsg ==  "KEY_INVALIDATED" then
			return luna_xyz_env:KeyFail(KeyWindow, errorMsg, "The provided key was manually disabled.");
		end;

		if errorMsg ==  "HWID_MISMATCH" then
			return luna_xyz_env:KeyFail(KeyWindow, errorMsg, "The provided key is linked to another HWID.");
		end;

		if errorMsg ==  "SERVICE_NOT_FOUND" then
			return luna_xyz_env:KeyFail(KeyWindow, errorMsg, "Internal server error, ERROR: Service does not exist or not found.");
		end;

		if errorMsg ==  "ERROR" or errorMsg:match("^http %d+")then
			return luna_xyz_env:KeyFail(KeyWindow, errorMsg, string.format("Internal server error, ERROR: %s", tostring(errorMsg)));
		end;
	end);
	
	luna_xyz_env.LoadingUI:Destroy(); luna_xyz_env.LoadingUI = nil;
end)

repeat task.wait(); until user_authenticated;
if KeyWindow then KeyWindow:Toggle(false); end;

luna_xyz_env.LoadingUI = luna_xyz_env.LoadingUI or UILibrary:CreateLoading({
	
	Title = ('luna.xyz - %s'):format(tostring(luna_xyz_env.versions["luna_xyz_loader"]));
	TotalSteps = 15; Icon = 5012126105; IconSize = UDim2.fromOffset(20, 20);
});

luna_xyz_env.LoadingUI:SetMessage("Initializing luna.xyz");
luna_xyz_env:SetProgress("User Authenticated.", 7);

Logger.success('User Authenticated.');

